using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace PixelForge {
public sealed partial class MainWindow {
    public async Task StudioSmoke(string dir){Directory.CreateDirectory(dir);try{
        BackgroundLibrary.Root=Path.Combine(dir,"first-library");RecentProjects.FilePath=Path.Combine(dir,"settings","recent.json");
        Demo();await backgrounds.Demo();var entry=await backgrounds.TestAutomaticGallery();if(entry==null||!File.Exists(entry.FilePath)||!File.Exists(entry.ThumbnailPath)||BackgroundLibrary.List().Count!=1)throw new Exception("Gallery background/thumbnail save failed");var p=BackgroundLibrary.Load(entry.Id);if(!AmbientEngine.Render(p,.5).Data.SequenceEqual(AmbientEngine.Render(backgrounds.CaptureWorkspace(),.5).Data))throw new Exception("Gallery masks/settings round-trip failed");
        var frames=await Task.Run(()=>AmbientEngine.Frames(p,CancellationToken.None));cutscenes.InstallWorkspace(new Cutscene());cutscenes.AddAmbient(p,frames);cutscenes.AddSequence(new List<Frame>(this.frames),"Персонаж",12);mainTabs.SelectedIndex=1;var expected=SceneRenderer.Render(cutscenes.CaptureWorkspace(),.25);var expectedSprites=(byte[])this.frames[0].Data.Clone();
        var savedView=new StudioManifest {SceneTime=.37,SelectedLayer=cutscenes.CaptureWorkspace().Layers.Last().Id,ScenePanel=1,BackgroundFrame=5,SelectedRegion=p.Regions[0].Id,BackgroundPanel=1};cutscenes.RestoreWorkspaceView(savedView);backgrounds.RestoreWorkspaceView(savedView);Select(3);
        string fixture=Path.Combine(Environment.CurrentDirectory,"work","test.avi"),originalVideo=Path.Combine(dir,"original-video.avi");byte[] videoBytes=null;if(File.Exists(fixture)){File.Copy(fixture,originalVideo,true);videoPath=originalVideo;videoBytes=File.ReadAllBytes(originalVideo);}
        studioPath=Path.Combine(dir,"portable.pfstudio");if(!await SaveStudio(false)||StudioHasChanges||!File.Exists(studioPath))throw new Exception("Unified save failed or left dirty flags");string savedPath=studioPath;var detached=await Task.Run(()=>StudioFile.Load(savedPath));if(!SceneRenderer.Render(detached.Scene,.25).Data.SequenceEqual(expected.Data)||!detached.Manifest.Sprites.Frames[0].Data.SequenceEqual(expectedSprites)||detached.Background.Photo==null||detached.Background.Regions.Count!=2||detached.Library.Count!=1)throw new Exception("Unified package did not preserve all documents/resources");if(detached.Manifest.VideoEntry==null&&videoBytes!=null)throw new Exception("Original video not embedded");
        if(File.Exists(originalVideo))File.Delete(originalVideo);BackgroundLibrary.Root=Path.Combine(dir,"empty-library");studioRestoring=true;InstallSprites(new SpriteWorkspace());cutscenes.InstallWorkspace(new Cutscene());backgrounds.InstallWorkspace(new AmbientProject());studioPath=null;studioDirty=false;studioRestoring=false;
        if(!await OpenStudio(savedPath)||StudioHasChanges||BackgroundLibrary.List().Count!=1||!framesEqual(expectedSprites,this.frames[0].Data)||!SceneRenderer.Render(cutscenes.CaptureWorkspace(),.25).Data.SequenceEqual(expected.Data))throw new Exception("Portable reopen without original files/gallery failed");if(videoBytes!=null&&(videoPath==null||!File.ReadAllBytes(videoPath).SequenceEqual(videoBytes)))throw new Exception("Embedded video recovery failed");var restoredView=CaptureStudio().Manifest;if(Math.Abs(restoredView.SceneTime-.37)>.00001||restoredView.SelectedLayer!=savedView.SelectedLayer||restoredView.BackgroundFrame!=5||current!=3)throw new Exception("Playhead/selection/frame state did not restore");StudioFile.CleanupVideo(detached.VideoPath);
        string oldId=backgrounds.CaptureWorkspace().LibraryId;var newer=BackgroundLibrary.Load(oldId);newer.Name="Более новая версия галереи";BackgroundLibrary.Upsert(newer);if(!await OpenStudio(savedPath))throw new Exception("Second open failed");if(BackgroundLibrary.Load(oldId).Name!="Более новая версия галереи"||BackgroundLibrary.List().Count!=2||backgrounds.CaptureWorkspace().LibraryId==oldId)throw new Exception("Project import overwrote newer gallery content instead of preserving both");
        string corrupt=Path.Combine(dir,"corrupt.pfstudio");File.WriteAllText(corrupt,"broken zip");var beforeCorrupt=SceneRenderer.Render(cutscenes.CaptureWorkspace(),.25);if(await OpenStudio(corrupt)||!SceneRenderer.Render(cutscenes.CaptureWorkspace(),.25).Data.SequenceEqual(beforeCorrupt.Data))throw new Exception("Bad project altered current workspace");
        byte[] goodFile=File.ReadAllBytes(savedPath);var invalid=CaptureStudio();invalid.Library[Guid.NewGuid().ToString("N")]=new AmbientProject();bool refused=false;try{await Task.Run(()=>StudioFile.Save(invalid,savedPath));}catch{refused=true;}if(!refused||!File.ReadAllBytes(savedPath).SequenceEqual(goodFile))throw new Exception("Failed save damaged previous project");
        RecentProjects.Touch(savedPath);RecentProjects.Touch(savedPath);if(RecentProjects.List().Count!=1||RecentProjects.List()[0].Path!=Path.GetFullPath(savedPath))throw new Exception("Recent project list duplicates or path mismatch");UpdateStudioTitle();ShowHome();UpdateLayout();await Task.Delay(100);var shot=new RenderTargetBitmap((int)ActualWidth,(int)ActualHeight,96,96,PixelFormats.Pbgra32);shot.Render(this);Frame.From(shot).Save(Path.Combine(dir,"start-menu.png"));ShowWorkspace(3);gallery.Refresh();UpdateLayout();await Task.Delay(100);shot=new RenderTargetBitmap((int)ActualWidth,(int)ActualHeight,96,96,PixelFormats.Pbgra32);shot.Render(this);Frame.From(shot).Save(Path.Combine(dir,"background-gallery.png"));
        File.WriteAllText(Path.Combine(dir,"studio-checks.txt"),"PASS: asynchronous gallery auto-save and thumbnail; editable background/mask recovery; unified project saves scene, sprite originals/edits and background resources; original video embedded and restored after deleting source; portable reopen in empty gallery; newer gallery version preserved with imported copy; broken open leaves current project unchanged; failed save preserves previous file byte-for-byte; recent-project deduplication; home and gallery rendering.\r\n");Application.Current.Shutdown(0);
    }catch(Exception ex){File.WriteAllText(Path.Combine(dir,"studio-error.txt"),ex.ToString());Application.Current.Shutdown(1);}}
    static bool framesEqual(byte[] a,byte[] b){return a.SequenceEqual(b);}
}
}

